		// It's a replacement func!
		int index = op.encoding & 0xFFFFFF;
		const ReplacementTableEntry *entry = GetReplacementFunc(index);
		if (entry) {
			entry->replaceFunc();
		} else {
			ERROR_LOG(CPU, "Bad replacement function index %i", index);
		}	

		PC = currentMIPS->r[MIPS_REG_RA];
	}

