+void VertexDecoderJitCache::Jit_PosFloatThrough() {
+	// Start by copying 8 bytes, then handle Z separately to clamp it.
+	LW(tempReg1, srcReg, dec_->posoff);
+	LW(tempReg2, srcReg, dec_->posoff + 4);
+	FL(32, fpSrc[2], srcReg, dec_->posoff + 8);
+	SW(tempReg1, dstReg, dec_->decFmt.posoff);
+	SW(tempReg2, dstReg, dec_->decFmt.posoff + 4);
+
+	// Load the constants to clamp.  Maybe could static alloc this constant in a reg.
+	LI(scratchReg, const65535);
+	FMV(FMv::W, FMv::X, fpScratchReg1, R_ZERO);
+	FMV(FMv::W, FMv::X, fpScratchReg2, scratchReg);
+
+	FMAX(32, fpSrc[2], fpSrc[2], fpScratchReg1);
+	FMIN(32, fpSrc[2], fpSrc[2], fpScratchReg2);
+	FS(32, fpSrc[2], dstReg, dec_->decFmt.posoff + 8);
+}
+
+void VertexDecoderJitCache::Jit_Color8888() {
+	LW(tempReg1, srcReg, dec_->coloff);
+
+	// Set tempReg2=-1 if full alpha, 0 otherwise.
+	SRLI(tempReg2, tempReg1, 24);
+	SLTIU(tempReg2, tempReg2, 0xFF);
+	ADDI(tempReg2, tempReg2, -1);
+
+	// Now use that as a mask to set/clear fullAlpha.
+	AND(fullAlphaReg, fullAlphaReg, tempReg2);
+
+	SW(tempReg1, dstReg, dec_->decFmt.c0off);
+}
+
+void VertexDecoderJitCache::Jit_AnyS8ToFloat(int srcoff) {
+	LB(tempReg1, srcReg, srcoff + 0);
+	LB(tempReg2, srcReg, srcoff + 1);
+	LB(tempReg3, srcReg, srcoff + 2);
+	// TODO: Could maybe static alloc?
+	LI(scratchReg, by128);
+	FMV(FMv::W, FMv::X, fpScratchReg1, scratchReg);
+	FCVT(FConv::S, FConv::W, fpSrc[0], tempReg1, Round::TOZERO);
+	FCVT(FConv::S, FConv::W, fpSrc[1], tempReg2, Round::TOZERO);
+	FCVT(FConv::S, FConv::W, fpSrc[2], tempReg3, Round::TOZERO);
+	FMUL(32, fpSrc[0], fpSrc[0], fpScratchReg1);
+	FMUL(32, fpSrc[1], fpSrc[1], fpScratchReg1);
+	FMUL(32, fpSrc[2], fpSrc[2], fpScratchReg1);
+}
+
+void VertexDecoderJitCache::Jit_AnyS16ToFloat(int srcoff) {
+	LH(tempReg1, srcReg, srcoff + 0);
+	LH(tempReg2, srcReg, srcoff + 2);
+	LH(tempReg3, srcReg, srcoff + 4);
+	// TODO: Could maybe static alloc?
+	LI(scratchReg, by32768);
+	FMV(FMv::W, FMv::X, fpScratchReg1, scratchReg);
+	FCVT(FConv::S, FConv::W, fpSrc[0], tempReg1, Round::TOZERO);
+	FCVT(FConv::S, FConv::W, fpSrc[1], tempReg2, Round::TOZERO);
+	FCVT(FConv::S, FConv::W, fpSrc[2], tempReg3, Round::TOZERO);
+	FMUL(32, fpSrc[0], fpSrc[0], fpScratchReg1);
+	FMUL(32, fpSrc[1], fpSrc[1], fpScratchReg1);
+	FMUL(32, fpSrc[2], fpSrc[2], fpScratchReg1);
+}
+
+void VertexDecoderJitCache::Jit_AnyU8ToFloat(int srcoff, u32 bits) {
+	_dbg_assert_msg_((bits & ~(16 | 8)) == 0, "Bits must be a multiple of 8.");
+	_dbg_assert_msg_(bits >= 8 && bits <= 24, "Bits must be a between 8 and 24.");
+
+	LBU(tempReg1, srcReg, srcoff + 0);
+	if (bits >= 16)
+		LBU(tempReg2, srcReg, srcoff + 1);
+	if (bits >= 24)
+		LBU(tempReg3, srcReg, srcoff + 2);
+	// TODO: Could maybe static alloc?
+	LI(scratchReg, by128);
+	FMV(FMv::W, FMv::X, fpScratchReg1, scratchReg);
+	FCVT(FConv::S, FConv::WU, fpSrc[0], tempReg1, Round::TOZERO);
+	if (bits >= 16)
+		FCVT(FConv::S, FConv::WU, fpSrc[1], tempReg2, Round::TOZERO);
+	if (bits >= 24)
+		FCVT(FConv::S, FConv::WU, fpSrc[2], tempReg3, Round::TOZERO);
+	FMUL(32, fpSrc[0], fpSrc[0], fpScratchReg1);
+	if (bits >= 16)
+		FMUL(32, fpSrc[1], fpSrc[1], fpScratchReg1);
+	if (bits >= 24)
+		FMUL(32, fpSrc[2], fpSrc[2], fpScratchReg1);
+}
+
+void VertexDecoderJitCache::Jit_AnyU16ToFloat(int srcoff, u32 bits) {
+	_dbg_assert_msg_((bits & ~(32 | 16)) == 0, "Bits must be a multiple of 16.");
+	_dbg_assert_msg_(bits >= 16 && bits <= 48, "Bits must be a between 16 and 48.");
+
+	LHU(tempReg1, srcReg, srcoff + 0);
+	if (bits >= 32)
+		LHU(tempReg2, srcReg, srcoff + 2);
+	if (bits >= 48)
+		LHU(tempReg3, srcReg, srcoff + 4);
+	// TODO: Could maybe static alloc?
+	LI(scratchReg, by32768);
+	FMV(FMv::W, FMv::X, fpScratchReg1, scratchReg);
+	FCVT(FConv::S, FConv::WU, fpSrc[0], tempReg1, Round::TOZERO);
+	if (bits >= 32)
+		FCVT(FConv::S, FConv::WU, fpSrc[1], tempReg2, Round::TOZERO);
+	if (bits >= 48)
+		FCVT(FConv::S, FConv::WU, fpSrc[2], tempReg3, Round::TOZERO);
+	FMUL(32, fpSrc[0], fpSrc[0], fpScratchReg1);
+	if (bits >= 32)
+		FMUL(32, fpSrc[1], fpSrc[1], fpScratchReg1);
+	if (bits >= 48)
+		FMUL(32, fpSrc[2], fpSrc[2], fpScratchReg1);
+}
+
 #endif // PPSSPP_ARCH(RISCV64)

diff --git a/GPU/Common/VertexDecoderHandwritten.cpp b/GPU/Common/VertexDecoderHandwritten.cpp
index 8cfe310800..30be6d6f98 100644
--- a/GPU/Common/VertexDecoderHandwritten.cpp
+++ b/GPU/Common/VertexDecoderHandwritten.cpp
@@ -114,103 +114,160 @@ void VtxDec_Tu16_C8888_Pfloat(const u8 *srcp, u8 *dstp, int count, const UVScale
 void VtxDec_Tu8_C5551_Ps16(const u8 *srcp, u8 *dstp, int count, const UVScale *uvScaleOffset) {
 	struct GTAVTX {
 		union {
 			struct {
 				u8 u;
 				u8 v;
 			};
 			u16 uv;
 		};
 		u16 col;
 		s16 x;
 		s16 y;
 		s16 z;
 	};
 	// NOTE: This might be different for different vertex formats.
 	struct OutVTX {
 		float u;
 		float v;
 		uint32_t col;
 		float x;
 		float y;
 		float z;
 	};
 	const GTAVTX *src = (const GTAVTX *)srcp;
 	OutVTX *dst = (OutVTX *)dstp;
 	float uscale = uvScaleOffset->uScale * (1.0f / 128.0f);
 	float vscale = uvScaleOffset->vScale * (1.0f / 128.0f);
 	float uoff = uvScaleOffset->uOff;
 	float voff = uvScaleOffset->vOff;

-	u32 alpha = 0xFFFFFFFF;
+	uint64_t alpha = 0xFFFFFFFFFFFFFFFFULL;

 #if PPSSPP_ARCH(SSE2)
 	__m128 uvOff = _mm_setr_ps(uoff, voff, uoff, voff);
 	__m128 uvScale = _mm_setr_ps(uscale, vscale, uscale, vscale);
 	__m128 posScale = _mm_set1_ps(1.0f / 32768.0f);
 	__m128i rmask = _mm_set1_epi32(0x001F);
 	__m128i gmask = _mm_set1_epi32(0x03E0);
 	__m128i bmask = _mm_set1_epi32(0x7c00);
 	__m128i amask = _mm_set1_epi32(0x8000);
 	__m128i lowbits = _mm_set1_epi32(0x00070707);

 	// Two vertices at a time, we can share some calculations.
 	// It's OK to accidentally decode an extra vertex.
 	for (int i = 0; i < count; i += 2) {
 		__m128i pos0 = _mm_loadl_epi64((const __m128i *) & src[i].x);
 		__m128i pos1 = _mm_loadl_epi64((const __m128i *) & src[i + 1].x);
 		// Translate UV, combined. TODO: Can possibly shuffle UV and col together here
 		uint32_t uv0 = (uint32_t)src[i].uv | ((uint32_t)src[i + 1].uv << 16);
 		uint64_t col0 = (uint64_t)src[i].col | ((uint64_t)src[i + 1].col << 32);
 		__m128i pos0_32 = _mm_srai_epi32(_mm_unpacklo_epi16(pos0, pos0), 16);
 		__m128i pos1_32 = _mm_srai_epi32(_mm_unpacklo_epi16(pos1, pos1), 16);
 		__m128 pos0_ext = _mm_mul_ps(_mm_cvtepi32_ps(pos0_32), posScale);
 		__m128 pos1_ext = _mm_mul_ps(_mm_cvtepi32_ps(pos1_32), posScale);

 		__m128i uv8 = _mm_set1_epi32(uv0);
 		__m128i uv16 = _mm_unpacklo_epi8(uv8, uv8);
 		__m128i uv32 = _mm_srli_epi32(_mm_unpacklo_epi16(uv16, uv16), 24);
 		__m128d uvf = _mm_castps_pd(_mm_add_ps(_mm_mul_ps(_mm_cvtepi32_ps(uv32), uvScale), uvOff));
 		alpha &= col0;

 		// Combined RGBA
 		__m128i col = _mm_set1_epi64x(col0);
