+// IniFile
+// Taken from Dolphin but relicensed by me, Henrik Rydgard, under the MIT
+// license as I wrote the whole thing originally and it has barely changed.
+
+#include <stdlib.h>
+#include <stdio.h>
+
+#ifndef _MSC_VER
+#include <strings.h>
+#endif
+
+#include <string>
+#include <vector>
+#include <iostream>
+#include <fstream>
+#include <algorithm>
+
+#include "base/stringutil.h"
