 inline float curve1(float x) {
 	const float deadzone = 0.15f;
 	const float factor = 1.0f / (1.0f - deadzone);
 	if (x > deadzone) {
 		return (x - deadzone) * (x - deadzone) * factor;
 	} else if (x < -0.1f) {
 		return -(x + deadzone) * (x + deadzone) * factor;
 	} else {
 		return 0.0f;
 	}
 }

 inline float clamp1(float x) {
 	if (x > 1.0f) return 1.0f;
 	if (x < -1.0f) return -1.0f;
 	return x;
 }

