 	t.microsecond = ticks % 1000000ULL;

 	tm *local  = gmtime(&time);

 	t.year = local->tm_year + 1900 - numYearAdd * 400;
 	t.month = local->tm_mon + 1;
 	t.day = local->tm_mday;
 	t.hour = local->tm_hour;
 	t.minute = local->tm_min;
 	t.second = local->tm_sec;
 }

