 void getPixelColor(u8 r, u8 g, u8 b, u8 a, int pixelMode, u16* color)
 {
 	switch (pixelMode)
 	{
 	case TPSM_PIXEL_STORAGE_MODE_16BIT_BGR5650: 
 		{
 			*color = ((b >> 3) << 11) | ((g >> 2) << 5) | (r >> 3);
 		}
 		break;
