		ERROR_LOG(ME, "%08x=sceAtracDecodeData(%i, %08x, ...): Bad out addr, skipping", ret, atracID, outAddr);
		return SCE_KERNEL_ERROR_ILLEGAL_ADDR;
	}

	u32 numSamples = 0;
	u32 finish = 0;
