bool FixPathCase(const Path &realBasePath, std::string &path, FixPathCaseBehavior behavior) {
	if (realBasePath.Type() == PathType::CONTENT_URI) {
		// Nothing to do. These are already case insensitive, I think.
		return true;
	}

