+static inline u32 QuickTexHash(u32 addr, int bufw, int w, int h, u32 format) {
+	int pixToBytes = (bitsPerPixel[format < 11 ? format : 0] + 7) / 8;
+	int w32 = (w * pixToBytes + 3) / 4;
+	int pad32 = ((bufw * pixToBytes + 3) / 4) - w32;
