 bool RefCountedObject::Release() {
 	if (refcount_ > 0 && refcount_ < 10000) {
 		refcount_--;
 		if (refcount_ == 0) {
 			delete this;
 			return true;
 		}
 	}
 	else {
 		ELOG("Refcount (%d) invalid for object %p - corrupt?", refcount_, this);
 	}
 	return false;
 }

