 	storage.initialize(storage_capacity);
 	trace_info.reserve(max_trace_size);
 	INFO_LOG(Log::JIT, "MIPSTracer initialized: storage_capacity=0x%x, max_trace_size=%d", storage_capacity, max_trace_size);
 }

