 	} else {
 		enable = attrMask;
 		disable = ~attrMask;
 	}
 	for (int i = 0; i < ATTR_COUNT; i++) {
 		if (enable & (1 << i))
 			glEnableVertexAttribArray(i);
 		else if (disable & (1 << i))
 			glDisableVertexAttribArray(i);
 	}
