		g_code_chunk->CreateLocalCode(minsize, maxsize);
		g_code_heap = UserHeap::ChunkHeap(*g_code_chunk, minsize, 1, maxsize);
		g_next_ptr = (void*) g_code_heap->Alloc( minsize );
