+
+static void DrawLine(u8* target, DrawingCoords a, DrawingCoords b)
+{
+	if (a.x > b.x) {
+		DrawLine(target, b, a);
+		return;
+	}
+
+	if (a.y > b.y && a.x - b.x < a.y - b.y)
+	{
+		DrawVLine(target, a, b);
+		return;
+	}
+
+	if (a.y < b.y && a.x - b.x < b.y - a.y)
+	{
+		DrawVLine(target, a, b);
+		return;
+	}
+
+	for (int x = a.x; x < b.x; ++x) {
+		float u = (float)(x-a.x)/(float)(b.x-a.x);
+		int y = (1-u)*a.y+u*b.y;
