 		glDeleteShader(shader->second->fragShader);
 		glDeleteProgram(shader->second->program);
 		delete shader->second;
 	}
 	cache_.clear();
 	for (auto tex = texCache_.begin(); tex != texCache_.end(); ++tex) {
 		glDeleteTextures(1, &tex->second->texture);
 		delete tex->second;
 	}
 	texCache_.clear();
 }

