 std::string getFileExtension(const std::string &fn) {
 	int pos = (int)fn.rfind(".");
 	if (pos < 0) return "";
 	std::string ext = fn.substr(pos+1);
 	for (size_t i = 0; i < ext.size(); i++) {
 		ext[i] = tolower(ext[i]);
 	}
 	return ext;
 }

