+// Gets a number of bits from an offset.
+// TODO: Make more efficient.
+static int getBits(int numBits, const u8 *buf, size_t pos) {
+	int v = 0;
+	for (int i = 0; i < numBits; i++) {
+		v = v | (((buf[pos >> 3] >> (pos & 7)) & 1) << i);
+		pos++;
+	}
+	return v;
+}
