+static std::vector<int> getTable(const u8 *buf, int bpe, int length) {
+	std::vector<int> vec;
+	vec.resize(length);
+	for (int i = 0; i < length; i++) {
+		vec[i] = getBits(bpe, buf, bpe * i);
+	}
+	return vec;
+}
